-- SERIES 1
SET NAMES utf8mb4;
DROP PROCEDURE IF EXISTS nova_en_v3_s001;
DELIMITER $$
CREATE PROCEDURE nova_en_v3_s001()
BEGIN
  DECLARE v_count INT DEFAULT 0;
  DECLARE v_course BIGINT UNSIGNED;
  DECLARE v_level BIGINT UNSIGNED;
  DECLARE v_module BIGINT UNSIGNED;
  DECLARE v_chapter BIGINT UNSIGNED;
  DECLARE v_c_arman BIGINT UNSIGNED;
  DECLARE v_c_maya BIGINT UNSIGNED;
  DECLARE v_l_1 BIGINT UNSIGNED; DECLARE v_l_2 BIGINT UNSIGNED; DECLARE v_l_3 BIGINT UNSIGNED; DECLARE v_l_4 BIGINT UNSIGNED;
  DECLARE v_u_hello BIGINT UNSIGNED; DECLARE v_u_goodbye BIGINT UNSIGNED; DECLARE v_u_name BIGINT UNSIGNED; DECLARE v_u_myname BIGINT UNSIGNED; DECLARE v_u_nicemeet BIGINT UNSIGNED; DECLARE v_u_howare BIGINT UNSIGNED; DECLARE v_u_pron BIGINT UNSIGNED;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  START TRANSACTION;

  SELECT COUNT(*),MIN(id) INTO v_count,v_course FROM courses WHERE learning_language='en' AND base_language='fa';
  IF v_count=0 THEN INSERT INTO courses (learning_language,base_language,title,title_translation,status,metadata) VALUES ('en','fa','English for Persian Speakers','انگلیسی برای فارسی‌زبان‌ها','active',JSON_OBJECT('contractVersion','3.0.0')); SET v_course=LAST_INSERT_ID(); ELSEIF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='en-fa course identity not unique'; END IF;
  SELECT COUNT(*),MIN(id) INTO v_count,v_level FROM levels WHERE course_id=v_course AND cefr_level='A1';
  IF v_count=0 THEN INSERT INTO levels (course_id,cefr_level,title,title_translation,difficulty_min,difficulty_max,sort_order,status,metadata) VALUES (v_course,'A1','A1 Foundations','پایه A1',1,2,1,'active',JSON_OBJECT('completionMode','dynamic_outcome_mastery')); SET v_level=LAST_INSERT_ID(); END IF;
  SELECT COUNT(*),MIN(id) INTO v_count,v_module FROM modules WHERE level_id=v_level AND sort_order=1;
  IF v_count=0 THEN INSERT INTO modules (level_id,title,title_translation,emoji,difficulty_min,difficulty_max,sort_order,status,metadata) VALUES (v_level,'First Connections','اولین ارتباط‌ها','👋',1,2,1,'active',JSON_OBJECT('dynamic',TRUE)); SET v_module=LAST_INSERT_ID(); END IF;

  SELECT COUNT(*),MIN(id) INTO v_count,v_c_arman FROM characters WHERE course_id=v_course AND name='Arman' AND gender='male';
  IF v_count=0 THEN INSERT INTO characters (course_id,name,gender,voice_key,profile,metadata) VALUES (v_course,'Arman','male','arman',JSON_OBJECT('role','زبان‌آموز و شخصیت اصلی'),JSON_OBJECT('context',NULL,'originCountry',NULL)); SET v_c_arman=LAST_INSERT_ID(); END IF;
  SELECT COUNT(*),MIN(id) INTO v_count,v_c_maya FROM characters WHERE course_id=v_course AND name='Maya' AND gender='female';
  IF v_count=0 THEN INSERT INTO characters (course_id,name,gender,voice_key,profile,metadata) VALUES (v_course,'Maya','female','maya',JSON_OBJECT('role','دوست آرمان در لندن'),JSON_OBJECT('context',NULL,'originCountry',NULL)); SET v_c_maya=LAST_INSERT_ID(); END IF;

  SELECT COUNT(*),MIN(id) INTO v_count,v_chapter FROM chapters WHERE module_id=v_module AND sort_order=1;
  IF v_count=0 THEN


    SELECT id INTO v_u_hello FROM learning_units WHERE course_id=v_course AND unit_key='en:a1:hello:greeting'; SELECT id INTO v_u_goodbye FROM learning_units WHERE course_id=v_course AND unit_key='en:a1:goodbye:parting'; SELECT id INTO v_u_name FROM learning_units WHERE course_id=v_course AND unit_key='en:a1:name:person-name'; SELECT id INTO v_u_myname FROM learning_units WHERE course_id=v_course AND unit_key='en:a1:my-name-is'; SELECT id INTO v_u_nicemeet FROM learning_units WHERE course_id=v_course AND unit_key='en:a1:nice-to-meet-you'; SELECT id INTO v_u_howare FROM learning_units WHERE course_id=v_course AND unit_key='en:a1:how-are-you'; SELECT id INTO v_u_pron FROM learning_units WHERE course_id=v_course AND unit_key='en:a1:pron:hello-stress';





  END IF;
  COMMIT;
END$$
DELIMITER ;
CALL nova_en_v3_s001();
DROP PROCEDURE IF EXISTS nova_en_v3_s001;
